"""
views/vm_list_view.py — sidebar VM list.

Shows ALL libvirt domains on qemu:///system (not filtered to BulwarkOS-only).
Includes a New VM button to open VMCreateDialog.
"""

import gi
gi.require_version("Gtk", "4.0")
gi.require_version("Adw", "1")

from gi.repository import Gtk, Adw
from typing import Callable

from gi.repository import Gdk
from ..backend.libvirt_manager import (
    DomainInfo, LibvirtManager, TRUST_LABELS, DEFAULT_TRUST_LEVELS
)
from .vm_create_dialog import VMCreateDialog


def _trust_color(trust: str, defs: dict) -> str:
    """Return the hex colour for a trust level ID, falling back to grey."""
    return defs.get(trust, defs.get("unknown", {})).get("color", "#888888")


_STATE_CSS = {
    "Running":       "success",
    "Stopped":       "",
    "Paused":        "warning",
    "Shutting down": "warning",
    "Crashed":       "error",
    "Suspended":     "warning",
}


class VMListView(Adw.NavigationPage):
    def __init__(
        self,
        on_select: Callable[[DomainInfo], None],
        manager: LibvirtManager,
    ):
        super().__init__(title="BulwarkOS", tag="vm-list")
        self._on_select = on_select
        self._manager   = manager
        self._rows: dict[str, tuple[Adw.ActionRow, Gtk.Label]] = {}
        self._domains: list[DomainInfo] = []
        self.selected_name: str | None = None

        # ── Header bar ────────────────────────────────────────────────────
        self._header = Adw.HeaderBar()
        self._header.set_show_end_title_buttons(False)

        # New VM button
        btn_new = Gtk.Button()
        btn_new.set_icon_name("list-add-symbolic")
        btn_new.set_tooltip_text("New virtual machine")
        btn_new.connect("clicked", self._on_new_vm)
        self._header.pack_end(btn_new)

        # ── Search ────────────────────────────────────────────────────────
        self._search_entry = Gtk.SearchEntry()
        self._search_entry.set_placeholder_text("Search VMs…")
        self._search_entry.connect("search-changed", lambda _: self._list_box.invalidate_filter())

        # ── List ──────────────────────────────────────────────────────────
        self._list_box = Gtk.ListBox()
        self._list_box.set_selection_mode(Gtk.SelectionMode.SINGLE)
        self._list_box.add_css_class("navigation-sidebar")
        self._list_box.set_filter_func(self._filter_func)
        self._list_box.connect("row-selected", self._on_row_selected)

        scroll = Gtk.ScrolledWindow()
        scroll.set_policy(Gtk.PolicyType.NEVER, Gtk.PolicyType.AUTOMATIC)
        scroll.set_vexpand(True)
        scroll.set_child(self._list_box)

        # Spinner while connecting
        self._spinner = Gtk.Spinner()
        self._spinner.set_size_request(32, 32)
        self._spinner.set_halign(Gtk.Align.CENTER)
        self._spinner.set_valign(Gtk.Align.CENTER)
        self._spinner.start()

        self._stack = Gtk.Stack()
        self._stack.add_named(self._spinner, "loading")
        self._stack.add_named(scroll, "list")
        self._stack.set_visible_child_name("loading")

        # Empty state
        self._empty_label = Gtk.Label(label="No virtual machines found.")
        self._empty_label.add_css_class("dim-label")
        self._empty_label.set_margin_top(32)
        self._stack.add_named(self._empty_label, "empty")

        # ── Layout ────────────────────────────────────────────────────────
        toolbar = Adw.ToolbarView()
        toolbar.add_top_bar(self._header)
        toolbar.add_top_bar(self._search_entry)
        toolbar.set_content(self._stack)
        self.set_child(toolbar)

    # ------------------------------------------------------------------ #
    # Public                                                               #
    # ------------------------------------------------------------------ #

    def update(self, domains: list[DomainInfo]):
        self._domains = domains
        self._spinner.stop()

        seen: set[str] = set()
        for info in domains:
            seen.add(info.name)
            if info.name in self._rows:
                self._update_row(info)
            else:
                self._add_row(info)

        for name in list(self._rows.keys()):
            if name not in seen:
                row, _lbl, _dot = self._rows.pop(name)
                self._list_box.remove(row)

        self._list_box.invalidate_filter()
        self._stack.set_visible_child_name("list" if domains else "empty")

    # ------------------------------------------------------------------ #
    # Row construction                                                     #
    # ------------------------------------------------------------------ #

    def _add_row(self, info: DomainInfo):
        row = Adw.ActionRow()
        row.set_activatable(True)

        # Trust colour dot — rendered with the level's exact hex colour
        trust_dot = Gtk.DrawingArea()
        trust_dot.set_size_request(10, 10)
        trust_dot.set_valign(Gtk.Align.CENTER)
        defs_snap = self._manager.get_trust_defs()
        hex_color = _trust_color(info.meta.get("trust", "unknown"), defs_snap)

        def _draw(da, cr, w, h, hx=hex_color):
            rgba = Gdk.RGBA()
            rgba.parse(hx)
            cr.set_source_rgba(rgba.red, rgba.green, rgba.blue, 1.0)
            cr.arc(w / 2, h / 2, w / 2, 0, 2 * 3.14159)
            cr.fill()

        trust_dot.set_draw_func(_draw)
        row.add_prefix(trust_dot)

        # Icon
        icon = Gtk.Image.new_from_icon_name(
            info.meta.get("icon", "computer-symbolic")
        )
        icon.set_pixel_size(16)
        row.add_prefix(icon)

        # Title — use display label, not raw VM name
        row.set_title(info.meta.get("label", info.name))

        # Subtitle — raw VM name if different from label
        label = info.meta.get("label", info.name)
        if label != info.name:
            row.set_subtitle(info.name)

        # State label
        state_lbl = Gtk.Label(label=info.state_name)
        state_lbl.set_valign(Gtk.Align.CENTER)
        state_css = _STATE_CSS.get(info.state_name, "")
        if state_css:
            state_lbl.add_css_class(state_css)
        state_lbl.add_css_class("caption")
        row.add_suffix(state_lbl)

        row.set_name(info.name)
        # Store (row, state_lbl, trust_dot) so _update_row can refresh the dot
        self._rows[info.name] = (row, state_lbl, trust_dot)
        self._list_box.append(row)

    def _update_row(self, info: DomainInfo):
        row, state_lbl, trust_dot = self._rows[info.name]

        # Update label and subtitle
        display_label = info.meta.get("label", info.name)
        row.set_title(display_label)
        row.set_subtitle(info.name if display_label != info.name else "")

        # Update state label
        state_lbl.set_label(info.state_name)
        for cls in ("success", "warning", "error", "accent"):
            state_lbl.remove_css_class(cls)
        state_css = _STATE_CSS.get(info.state_name, "")
        if state_css:
            state_lbl.add_css_class(state_css)

        # Update trust dot colour — replace the draw function with a new closure
        # capturing the current trust colour, then force a redraw
        defs_snap  = self._manager.get_trust_defs()
        new_color  = _trust_color(info.meta.get("trust", "unknown"), defs_snap)

        def _draw_updated(da, cr, w, h, hx=new_color):
            rgba = Gdk.RGBA()
            rgba.parse(hx)
            cr.set_source_rgba(rgba.red, rgba.green, rgba.blue, 1.0)
            cr.arc(w / 2, h / 2, w / 2, 0, 2 * 3.14159)
            cr.fill()

        trust_dot.set_draw_func(_draw_updated)
        trust_dot.queue_draw()



    # ------------------------------------------------------------------ #
    # Selection                                                            #
    # ------------------------------------------------------------------ #

    def _on_row_selected(self, _, row):
        if row is None:
            return
        name = row.get_name()
        self.selected_name = name
        for info in self._domains:
            if info.name == name:
                self._on_select(info)
                return

    # ------------------------------------------------------------------ #
    # Filter                                                               #
    # ------------------------------------------------------------------ #

    def _filter_func(self, row) -> bool:
        query = self._search_entry.get_text().lower().strip()
        if not query:
            return True
        name = row.get_name().lower()
        # Also search display label
        for info in self._domains:
            if info.name == row.get_name():
                label = info.meta.get("label", "").lower()
                return query in name or query in label
        return query in name

    # ------------------------------------------------------------------ #
    # New VM                                                               #
    # ------------------------------------------------------------------ #

    def _on_new_vm(self, _btn):
        dialog = VMCreateDialog(
            manager=self._manager,
            on_created=self._on_vm_created,
            parent=self,
        )
        dialog.present(self)

    def _on_vm_created(self, name: str):
        # The libvirt event will trigger a list refresh automatically.
        # Auto-select the new VM once it appears.
        self.selected_name = name
